"tribe": "ハチ",
"atk": 1,
"def": 1,
"effect": "《有翼》《有毒》\n【誘発（戦場）】［これが戦場に出た時に発動してもよい。］あなたのデッキからコスト1以下で互いに異なるカード名のみを持つハチ動物カード最大2枚を探して、『【誘発（戦場）】［日没フェイズ開始時に発動する。］これを生贄に捧げる。』をターン終了時まで得た状態であなたの戦場に出す。\n【起動（墓地）】［場面タイミング中のみ起動できる。あなたの<森林域>が2以上なら、あなたの戦場の「蜂の巣」道具とあなたの領地の領土を任意の数ムーブして、あなたの墓地のこれをデッキの下に置いて発動する。］あなたの手札のコストXのハチ動物カード1枚を、防護カウンター1個が置かれた状態であなたの戦場に出す。Xはこの効果でムーブした道具と領土の数を合計した数に等しい。",
